-- 如果不是管理员,则不会创建调试器
function WukongDebugger.new(options: {
	toggleKey: Enum.KeyCode?,
	minimizeKey: Enum.KeyCode?,
}?)
	options = options or {}
	local self = {
		Wukong = wukong,
		Plasma = plasma,
		Root = nil,
		ExecuteRes = nil,
		WKTimer = WKTimer(c2lTimer),
		Favorites = {},
		ObjectStack = {},
		Operations = {},
		CurrentUserId = LocalPlayer.UserId,
		CurrentCreatedTime = 0,

		_favFilters = {},
		_enabled = false,
		_customWidgets = {},
		_running = nil,
		_isClientDev = false,
		_mini = false,

		_isAdmin = false,
		_isMod = false,
	}

	pcall(function()
		local identifies = remoteFunction:InvokeServer("GetIdentify")
		self._isAdmin = identifies.IsAdmin
		self._isMod = identifies.IsMod
		self._adminCommands = identifies.AdminCommands
		self._modCommands = identifies.ModCommands
	end)

	setmetatable(self, WukongDebugger)

	self:LoadFavoriteFilters()
	self:LoadFuncs()
	self:AutoLoad()
	self:CheckClientDev()

	for name, create in customWidgetConstructors do
		self._customWidgets[name] = create(self.Plasma)
	end

	local parent = Instance.new("ScreenGui")
	parent.Name = "WuKongDebugger"
	parent.DisplayOrder = 2 ^ 31 - 1
	parent.ResetOnSpawn = false
	parent.IgnoreGuiInset = true

	if IS_CLIENT then
		parent.Parent = Players.LocalPlayer:WaitForChild("PlayerGui")
	else
		parent.Parent = ReplicatedStorage
	end

	local _plasmaNode = self.Plasma.new(parent)
	self._plasmaNode = _plasmaNode

	-- 绑定快捷键
	local toggleKey = options.toggleKey or Enum.KeyCode.F6
	local minimizeKey = options.minimizeKey or Enum.KeyCode.F7
	ContextActionService:BindAction("WukongDebuggerToggle", function(_, state, input: InputObject)
		if state == Enum.UserInputState.Begin then
			if input.KeyCode == toggleKey then
				self:Toggle()
			elseif input.KeyCode == minimizeKey then
				self:Minimize()
			end

			return Enum.ContextActionResult.Sink
		end
	end, false, toggleKey, minimizeKey)

	if game.UserInputService.TouchEnabled then
		local gui = Instance.new("ScreenGui", game.Players.LocalPlayer:WaitForChild("PlayerGui"))
		gui.Name = "WukongDebugger"
		gui.SafeAreaCompatibility = Enum.SafeAreaCompatibility.FullscreenExtension
		gui.ScreenInsets = Enum.ScreenInsets.TopbarSafeInsets
		gui.DisplayOrder = 10 ^ 6
		gui.IgnoreGuiInset = true
		gui.ResetOnSpawn = false

		local frame = Instance.new("Frame", gui)
		frame.Size = UDim2.fromScale(1, 1)
		frame.BackgroundTransparency = 1

		local uilistLayout = Instance.new("UIListLayout", gui)
		uilistLayout.Padding = UDim.new(0, 10)
		uilistLayout.FillDirection = Enum.FillDirection.Horizontal

		local uipadding = Instance.new("UIPadding", gui)
		uipadding.PaddingTop = UDim.new(0.15, 0)
		uipadding.PaddingBottom = UDim.new(0.15, 0)
		uipadding.PaddingLeft = UDim.new(0, 10)

		local TextButton = Instance.new("TextButton", frame)
		TextButton.BackgroundColor3 = Color3.fromRGB(40, 40, 40)
		TextButton.Text = "Debugger"
		TextButton.AutomaticSize = Enum.AutomaticSize.X
		TextButton.TextScaled = true
		TextButton.Size = UDim2.fromScale(0, 1)
		TextButton.TextColor3 = Color3.fromRGB(220, 220, 220)

		TextButton.MouseButton1Click:Connect(function()
			self:Toggle()
			if self._enabled then
				uipadding.PaddingLeft = UDim.new(0, 150)
			else
				uipadding.PaddingLeft = UDim.new(0, 10)
			end
		end)
	end

	WukongDebugger.Inst = self
	return self
end

function WukongDebugger:InitData()
	local function loop(wkdata)
		if not wkdata._item then
			return
		end

		if #self._favFilters > 0 then
			table.clear(self.Favorites)
			local isFav = false
			for i, v in ipairs(self._favFilters) do
				if wkdata._item.Id and wkdata._item.Id:find(v) then
					isFav = true
					break
				end
			end
			if isFav then
				table.insert(self.Favorites, wkdata)
			end
		end

		if self.Wukong:IsSlot(wkdata._item) then
			wkdata._type = "Slot"
			-- 判断是不是容器
			local s: wukong.Slot = wkdata._item
			--print("Slot:" .. s:getPath())
			local element = s:getElement()
			if element then
				local d = WKData.new(element, wkdata)
				table.insert(wkdata._children, d)
				loop(d)
			end
		elseif wukong:IsContainer(wkdata._item) then
			wkdata._type = "Container"
			-- 判断是不是容器
			local c: wukong.Container = wkdata._item
			if wukong:IsElementContainer(c) then
				-- print(wkdata._item.ElementType)
				wkdata._type2 = "ElementContainer"
				-- warn("ElementContainer:" .. c:getPath())
			elseif wukong:IsAggregateContainer(c) then
				wkdata._type2 = "AggregateContainer"
				-- warn("AggregateContainer:" .. c:getPath())
			else
				-- warn("Container:" .. c:getPath())
			end
			local children = c:getChildren()
			if not children then
				return
			end
			for i, v in ipairs(children) do
				local d = WKData.new(v, wkdata)
				table.insert(wkdata._children, d)
				loop(d)
			end
		elseif wukong:IsPropertyItem(wkdata._item) then
			wkdata._type = "PropertyItem"
			local c: wukong.PropertyItem = wkdata._item
			--print("IsPropertyItem:" .. wkdata._item:getId())
			-- 其次,判断是不是属性物品,其优先级要高于判断元素
			if wkdata._item.PropertyContainer ~= "" then
				if wukong:IsElementContainer(wkdata._item.PropertyContainer) then
					local children = wkdata._item.PropertyContainer:getChildren()
					if not children then
						return
					end
					for i, v in ipairs(children) do
						local d = WKData.new(v, wkdata)
						table.insert(wkdata._children, d)
						loop(d)
					end
				end
				--local d = WKData.new(wkdata._item.PropertyContainer, wkdata)
				--table.insert(wkdata._children, d)
				--loop(d)
			end
		elseif wukong:IsElement(wkdata._item) then
			wkdata._type = "Element"
			--print("IsElement:" .. wkdata._item:getId())
		else
			error("漏了什么?")
			-- 最后判断元素
		end
	end

	if self._isAdmin then
		local root = wukong:GetRootContainer()
		self.Root = WKData.new(root, nil)
		loop(self.Root)
	else
		self.Root = {
			GetChildren = function()
				return {}
			end,
		}
	end
end

local function getPlayerConfig(configName)
	local playerId = tostring(Players.LocalPlayer.UserId)
	if __developer and __developer:FindFirstChild(playerId) then
		return __developer[playerId]:FindFirstChild(configName)
	end
end

function WukongDebugger:CheckClientDev()
	local config = getPlayerConfig("悟空客户端调试开关")
	if config then
		self._isClientDev = config.Value
	end
end

function WukongDebugger:LoadFavoriteFilters()
	local filterFolder = getPlayerConfig("fav")
	if filterFolder then
		for i, v in pairs(filterFolder:GetChildren()) do
			table.insert(self._favFilters, v.Name)
		end
	end
end

