function WukongDebugger:ReLoad()
	print("HotReloading......")
	local paths = {}
	for i, v in pairs(self.ObjectStack) do
		local path = v.value:GetPath()
		table.insert(paths, path)
	end

	table.clear(self.ObjectStack)
	table.clear(self.Operations)
	self.ExecuteRes = nil
	self:InitData()

	local object = nil
	while #paths > 0 do
		local p = table.remove(paths, 1)
		local temp = nil
		if p == "/" then
			temp = self.Root
		else
			local parent = object or self.Root
			for i, v in pairs(parent._children) do
				if v:GetPath() == p then
					temp = v
					break
				end
			end
		end
		if temp then
			table.insert(self.ObjectStack, {
				key = temp._item.Id,
				icon = nil,
				value = temp,
			})
		else
			break
		end
		object = temp
	end
end

function WukongDebugger:AutoLoad()
	self:InitData()

	-- 监听hotreload事件
	HotReloadEvent.Event:Connect(function()
		self:ReLoad()
	end)
end

function WukongDebugger:Show()
	self._running = RunService.Heartbeat:Connect(function()
		self.Plasma.beginFrame(self._plasmaNode, function()
			ui(self)
		end)
	end)
end

function WukongDebugger:Hide()
	if self._running then
		self._running:Disconnect()
		self._running = nil
	end
	if self._plasmaNode then
		self.Plasma.start(self._plasmaNode, function() end)
	end
end

function WukongDebugger:Toggle()
	self._mini = false
	if self._enabled then
		self:Disable()
	else
		self:Enable()
	end
end

function WukongDebugger:Minimize()
	self._mini = not self._mini
end

function WukongDebugger:Update()
	ui(self)
end

function WukongDebugger:Enable()
	self._enabled = true
	self:Show()
end

function WukongDebugger:Disable()
	self._enabled = false
	self:Hide()
end

function WukongDebugger:Destroy() end

local filters = {
	Cfg = true,
	Parent = true,
	Tables = true,
}

function getTable(t)
	local function loop(t, temp)
		-- 深拷贝
		for i, v in pairs(t) do
			if not filters[i] then
				if typeof(v) == "table" then
					temp[i] = {}
					loop(v, temp[i])
				else
					temp[i] = v
				end
			end
		end
	end
	local temp = {}
	loop(t, temp)
	return temp
end

function WukongDebugger:Save()
	print("Save")
	local c = WuKongContainerLoader.GetCurrentContainer()
	local data = WuKongContainerLoader.SerializeWuKongContainer(c)

	local id = self.CurrentUserId

	remoteEvent:FireServer("Save", id, data)
end

function WukongDebugger:Change(idstr)
	local userId = (idstr:gsub("^%s*(.-)%s*$", "%1"))
	if userId == "" then
		warn("Id不能为空")
		return
	end
	print("Change:" .. userId)
	remoteEvent:FireServer("Change", userId)
end

function WukongDebugger:Json()
	local c = WuKongContainerLoader.GetCurrentContainer()
	local data = WuKongContainerLoader.SerializeWuKongContainer(c)
	print("Json:", self.CurrentUserId, os.date("%Y-%m-%d %H:%M:%S", self.CurrentCreatedTime - 0))
	print(data)
	print(game.HttpService:JSONEncode(data))
end

function WukongDebugger:ClientChange(userId, data)
	if not data then
		warn("不存在" .. userId .. "数据，反序列化失败")
		return
	end
	-- data.Id = userId
	local container = WuKongContainerLoader.DeserializeWuKongContainer(tostring(userId), data)
	WuKongContainerLoader.SetContainer(container)
	self.CurrentUserId = userId
	self:ReLoad()
	print("Change:" .. userId .. " 成功")
end

remoteEvent.OnClientEvent:Connect(function(cmd, ...)
	local paras = { ... }
	if cmd == "Change" then
		WukongDebugger.Inst:ClientChange(paras[1], paras[2])
	elseif cmd == "CreatedTime" then
		local userId = paras[1]
		local t = paras[2]
		if WukongDebugger.Inst.CurrentUserId == userId then
			WukongDebugger.Inst.CurrentCreatedTime = t
		end
	elseif cmd == "Saved" then
		print("保存成功")
	end
end)

return WukongDebugger
